import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate basic counts
    opp_c = 0
    opp_d = 0
    my_d = 0
    cc = 0
    dd = 0
    for (me, opp) in history:
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
            if me == 'D':
                dd += 1
            else:
                pass
        if me == 'D':
            my_d += 1
        if me == 'C' and opp == 'C':
            cc += 1

    rounds_left = 100 - n
    opp_rate_c = opp_c / float(n)
    opp_rate_d = opp_d / float(n)

    if n == 1:
        # Opponent opener behavior signals.
        if history[0][1] == 'D':
            return 'D'
        return 'C'

    last_me, last_op = history[-1]

    # Recent windows
    recent_len = 6 if n >= 6 else n
    recent_opp = history[-recent_len:]
    recent_d = 0
    recent_c = 0
    for (m, o) in recent_opp:
        if o == 'D':
            recent_d += 1
        else:
            recent_c += 1

    # Opponent defection run length
    run_o = 0
    for (m, o) in reversed(history):
        if o == 'D':
            run_o += 1
        else:
            break
    run_o_c = 0
    for (m, o) in reversed(history):
        if o == 'C':
            run_o_c += 1
        else:
            break

    # Very exploitative opponent: defect with tiny probes.
    if opp_d >= 3 and opp_rate_d > 0.65:
        if rounds_left <= 4:
            return 'D'
        # Rarely probe for hidden cooperativeness early/mid.
        if n < 80 and rng.random() < 0.04:
            return 'C'
        return 'D'

    # Very cooperative opponent: max exploitation late, but cooperate most of time.
    if opp_d == 0:
        if n >= 12:
            # Start exploiting a pure cooperator in later game.
            if rounds_left <= 2:
                return 'D'
            if n >= 30 and rng.random() < 0.55:
                return 'D'
            if n >= 60:
                return 'D'
        return 'C'

    # Endgame adjustments: take advantage unless mutual defection danger.
    if rounds_left <= 3:
        if opp_rate_c > 0.9 and n >= 8:
            return 'D'
        if opp_rate_d > 0.6:
            return 'D'
        # Mixed, prefer D for last-round payoff edge if opponent not pure cooperator.
        if opp_d >= 1:
            return 'D'
        return 'C'

    if rounds_left <= 8:
        if opp_rate_c > 0.85:
            if last_op == 'C':
                return 'D'
            return 'D'
        if opp_rate_d > 0.5:
            return 'D'
        if last_op == 'D':
            return 'D'
        # Moderate coop: defect a lot near end.
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Short history regime: build cooperation, retaliate only to repeated D.
    if n < 5:
        if opp_d >= 2:
            return 'D'
        return 'C'

    # Detect highly defective opponent beyond threshold
    if opp_rate_d > 0.45:
        if last_op == 'D':
            # Strong retaliate, but occasional C to try to break loop.
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        # Opponent just cooperated. If recent D high, still defect.
        if recent_d >= 3:
            return 'D'
        # If they show a couple of C after D phase, reward.
        if recent_c >= 3:
            return 'C'
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Moderate-defection opponent (0.15 to 0.45)
    if opp_rate_d > 0.15:
        # Long defection run: retaliate but with sparse forgiveness.
        if run_o >= 3:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        # Recent defection intensity
        if recent_d >= 3:
            return 'D'
        if recent_d == 2:
            if last_op == 'D':
                if rng.random() < 0.2:
                    return 'C'
                return 'D'
            if rng.random() < 0.6:
                return 'D'
            return 'C'
        # Single recent defection: measured retaliation, favor C if we caused DD.
        if last_op == 'D':
            if last_me == 'D':
                # mutual defection - try to restore with C sometimes
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            return 'D'
        # last_op C, previous defections moderate
        if recent_c >= 4:
            return 'C'
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    # Low defection opponent (<=0.15): cooperate, probe opportunistically.
    if last_op == 'D':
        # Mostly forgive a rare defection; punish only if repeated.
        if run_o >= 2:
            return 'D'
        if opp_d >= 2 and recent_d >= 2:
            return 'D'
        # Forgive single rare defection.
        return 'C'

    # Opponent just cooperated and is mostly cooperative.
    if opp_rate_d < 0.1:
        # Very safe: stay C, occasional probe when safe.
        if n >= 25 and n < 85 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Lower-moderate defection: keep reciprocating C, occasional probe.
    if n >= 20 and n < 85 and rng.random() < 0.05:
        return 'D'
    return 'C'
